select json_extract(c.value,'$.id') from json_each(?1) as c where json_extract(c.value,'$.label')='related-field' and json_extract(c.value,'$.explanation') in ('旧集合关系。反向显示：related-field；有向：false。','从旧集合关系迁移。反向显示：related-field；有向：false。') and not exists(select 1 from json_tree(?2) as term where term.type='object' and json_extract(term.value,'$.kind')='concept' and json_extract(term.value,'$.id')=json_extract(c.value,'$.id')) and not exists(select 1 from json_each(?3) as a where json_extract(a.value,'$.targetKind')='concept' and json_extract(a.value,'$.targetId')=json_extract(c.value,'$.id')) and not exists(select 1 from json_each(?4) as r where r.value=json_extract(c.value,'$.id')) order by cast(c.key as integer)